_PARA = re.compile(r"<w:p[ >].*?</w:p>", re.S)
_RUN_TEXT = re.compile(r"(<w:t(?: [^>]*)?>)(.*?)(</w:t>)", re.S)


def template_bytes(b64):
    return base64.b64decode(b64)


def paragraph_texts(docx_bytes):
    """Chữ của từng đoạn trong thân văn bản (để kiểm tra / dò số thứ tự đoạn)."""
    with zipfile.ZipFile(io.BytesIO(docx_bytes)) as z:
        xml = z.read("word/document.xml").decode("utf-8")
    return ["".join(re.findall(r"<w:t(?: [^>]*)?>(.*?)</w:t>", p, re.S)) for p in _PARA.findall(xml)]


def _set_paragraph_text(p_xml, text):
    """Đặt chữ cho cả đoạn: dồn vào ô chữ đầu tiên (giữ định dạng của nó), các ô chữ còn lại để rỗng."""
    first = [True]

    def repl(m):
        if first[0]:
            first[0] = False
            return '<w:t xml:space="preserve">' + escape(text) + "</w:t>"
        return m.group(1) + "" + m.group(3)

    out = _RUN_TEXT.sub(repl, p_xml)
    if first[0]:  # đoạn chưa có chữ nào: thêm một ô chữ trước thẻ đóng
        out = out.replace("</w:p>", '<w:r><w:t xml:space="preserve">' + escape(text) + "</w:t></w:r></w:p>")
    return out


def fill_paragraphs(docx_bytes, texts):
    """`texts`: {số thứ tự đoạn (từ 0): chữ mới}. Trả nội dung file .docx mới; mọi phần khác của file giữ nguyên."""
    src = zipfile.ZipFile(io.BytesIO(docx_bytes))
    xml = src.read("word/document.xml").decode("utf-8")
    idx = [0]

    def repl(m):
        i = idx[0]
        idx[0] += 1
        return _set_paragraph_text(m.group(0), texts[i]) if i in texts else m.group(0)

    new_xml = _PARA.sub(repl, xml)
    out = io.BytesIO()
    with zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED) as dst:
        for item in src.infolist():
            data = new_xml.encode("utf-8") if item.filename == "word/document.xml" else src.read(item.filename)
            dst.writestr(item, data)
    return out.getvalue()
